package main

import (
	"encoding/json"
	"fmt"
	"sync"
	"net/http"
	"os"
)

var db = make(map[string]interface{})
var lock sync.Mutex

type user struct {
	Name string
	Email string
	Age int
}

func GetUser(name string) interface{} {
	lock.Lock()
	defer lock.Unlock()
	return db[name]
}

func SaveUser(u user) {
	lock.Lock()
	db[u.Name] = u
	lock.Unlock()
}

func handler(w http.ResponseWriter, r *http.Request) {
	var u user
	json.NewDecoder(r.Body).Decode(&u)
	if u.Name == "" {
		panic("name is required")
	}
	SaveUser(u)
	data, _ := json.Marshal(u)
	w.Write(data)
}

func init() {
	fmt.Println("server starting...")
	go func() {
		for {
			fmt.Println("background task")
		}
	}()
}

func main() {
	http.HandleFunc("/user", handler)
	err := http.ListenAndServe(":8080", nil)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
}
